            "html": "<span class=\"highlight-correct\"><span class=\"opt-tag tag-correct\">②</span><span class=\"explain-correct\" onclick=\"showTooltip(event, '男人首先提到了和纸在使用感受上的优点：【和纸有着柔软的独特质感，拿在手里能感觉到一种难以言喻的温暖。而且保存性也非常高，能够一直长久地使用（和紙には、独特の柔らかい質感があって……長く使い続けることができます）】。')\">和紙には、独特の柔らかい質感がって、手に取ると何とも言えない暖かさを感じます。</span></span>",
