            "end": 29.21,
            "status": "candidate",
            "humanAuditionPassed": false,
            "html": "今日は私の学生時代の話をしたいと思うんですけど。私学生時代、バスケットボールをやってたんですね。",
            "trans": "（今天我想讲讲我学生时代的故事。我学生时代，是打篮球的呢。）"
