  "2013.07-1": {
    "sampleAccurate": true,
    "endGuard": 0.06,
    "fadeOut": 0.018,
    "alignment": {
      "status": "user-approved",
      "humanAuditionPassed": false,
      "publicationApproval": {
        "type": "explicit-user-approval",
        "record": "output/audio/timeline-review/summary-n1-2013-07-redo/publication-approval.json",
        "candidateSha256": "8a4163d2ec3b58b7c314891d677e368b03cac9b1036a503724d5420dae50f35e"
      }
    },
    "question": {
      "src": "../assets/audio/2013.07-1.mp3",
      "start": 5.66,
      "end": 9.19,
      "status": "candidate",
      "humanAuditionPassed": false
    },
    "lines": [
      {
        "src": "../assets/audio/2013.07-1.mp3",
        "start": 11.03,
        "end": 26.1,
        "segments": [
          {
            "src": "../assets/audio/2013.07-1.mp3",
            "start": 11.03,
            "end": 17.72,
            "status": "candidate",
            "humanAuditionPassed": false,
            "html": "せっかく買った植物を出張や旅行で留守にした際に、<span class=\"keyword\" onclick=\"showTooltip(event, '枯（か）らす：使枯萎，弄枯。')\">枯らして</span>しまったという話を聞きます。",
            "trans": "（经常听到有人说，好不容易买的植物，却在出差或旅行不在家的时候枯死了。）"
          },
          {
            "src": "../assets/audio/2013.07-1.mp3",
            "start": 18.41,
            "end": 26.1,
            "status": "candidate",
            "humanAuditionPassed": false,
            "html": "留守中に<span class=\"keyword\" onclick=\"showTooltip(event, '植木（うえき）：盆栽，种植的树木。')\">植木</span>の世話を頼めるような<span class=\"keyword\" onclick=\"showTooltip(event, '近所付（きんじょづ）き合（あ）い：邻里交往，邻里关系。')\">近所付き合い</span>がある<span class=\"keyword\" onclick=\"showTooltip(event, 'に越（こ）したことはない：没有比……更好的了，最好是……。')\">に越したことはない</span>のですが、なかなかそうもいきませんよね。",
            "trans": "（如果能有那种在不在家时可以拜托帮忙照顾盆栽的邻里关系，自然是再好不过了，但往往很难如愿呢。）"
          }
        ]
      },
      {
        "src": "../assets/audio/2013.07-1.mp3",
        "start": 27.11,
        "end": 30.49,
        "status": "candidate",
        "humanAuditionPassed": false
      },
      {
        "src": "../assets/audio/2013.07-1.mp3",
        "start": 31.48,
        "end": 47.04,
        "segments": [
          {
            "src": "../assets/audio/2013.07-1.mp3",
            "start": 31.48,
            "end": 39.51,
            "status": "candidate",
            "humanAuditionPassed": false,
            "html": "<span class=\"highlight-correct\"><span class=\"opt-tag tag-correct\">④</span><span class=\"explain-correct\" onclick=\"showTooltip(event, '播音员明确指出【为了消除都市人的这种烦恼，某家园艺店推出了一项名为“植物保姆”的新服务（そんな都会人の悩みを解消しようと、ある園芸店がプラントシッターという新たなサービスを始めました）】，接下来都在具体介绍该服务，这符合选项4的“新举措”。')\">そんな都会人の悩みを<span class=\"keyword\" onclick=\"showTooltip(event, '解消（かいしょう）：消除，解除。')\">解消</span>しようと、ある<span class=\"keyword\" onclick=\"showTooltip(event, '園芸店（えんげいてん）：园艺店。')\">園芸店</span>がプラントシッターという新たなサービスを始めました。</span></span>",
            "trans": "（为了消除都市人的这种烦恼，某家园艺店推出了一项名为“植物保姆”的新服务。）"
          },
          {
            "src": "../assets/audio/2013.07-1.mp3",
            "start": 40.65,
            "end": 47.04,
            "status": "candidate",
            "humanAuditionPassed": false,
            "html": "<span class=\"highlight-correct\"><span class=\"explain-correct\" onclick=\"showTooltip(event, '播音员明确指出【为了消除都市人的这种烦恼，某家园艺店推出了一项名为“植物保姆”的新服务（そんな都会人の悩みを解消しようと、ある園芸店がプラントシッターという新たなサービスを始めました）】，接下来都在具体介绍该服务，这符合选项4的“新举措”。')\"></span></span>ペットを<span class=\"keyword\" onclick=\"showTooltip(event, '預（あず）かる：保管，收存，照管。')\">預かる</span>ように、植物を預かったり、客の家まで<span class=\"keyword\" onclick=\"showTooltip(event, '水（みず）やり：浇水。')\">水やり</span>に行くというものです。",
            "trans": "（就像寄养宠物一样，可以寄养植物，或者去客人家里浇水。）"
          }
        ]
      },
      {
        "src": "../assets/audio/2013.07-1.mp3",
        "start": 47.97,
        "end": 61.15,
        "segments": [
          {
            "src": "../assets/audio/2013.07-1.mp3",
            "start": 47.97,
            "end": 53.5,
            "status": "candidate",
            "humanAuditionPassed": false,
            "html": "私が知っている<span class=\"keyword\" onclick=\"showTooltip(event, '限（かぎ）り：只要……就……，在……范围内。')\">限り</span>、園芸店でこのような<span class=\"keyword\" onclick=\"showTooltip(event, '取（と）り組（く）み：举措，努力。')\">取り組み</span>をしている店はほかにありません。",
            "trans": "（据我所知，在园艺店中开展这种举措的店没有别家了。）"
          },
          {
            "src": "../assets/audio/2013.07-1.mp3",
            "start": 54.39,
            "end": 61.15,
            "status": "candidate",
            "humanAuditionPassed": false,
            "html": "専門店<span class=\"keyword\" onclick=\"showTooltip(event, 'ならでは：只有……才有的，非……莫属。')\">ならでは</span>の<span class=\"keyword\" onclick=\"showTooltip(event, '細（こま）やかな：细致的，无微不至的。')\">細やかな</span>対応で、新しい<span class=\"keyword\" onclick=\"showTooltip(event, '顧客獲得（こきゃくかくとく）：获取顾客。')\">顧客獲得</span>につなげていきたいと<span class=\"keyword\" onclick=\"showTooltip(event, '意気込（いきご）む：意气风发，干劲十足。')\">意気込んで</span>います。",
            "trans": "（他们意气风发地表示，希望能用专卖店特有的细致服务，来获取新的顾客。）"
          }
        ]
      },
      {
        "src": "../assets/audio/2013.07-1.mp3",
        "start": 66.96,
        "end": 70.92,
        "status": "candidate",
        "humanAuditionPassed": false
      }
    ]
  },
