            "html": "<span class=\"highlight-correct\"><span class=\"explain-correct\" onclick=\"showTooltip(event, '老师在开头就引出了话题：【一到秋天，树叶就会染上红色或黄色呢（秋になると、木の葉が赤や黄色に染まりますね）】。后续全文都在解释这个颜色变化的具体生理过程，符合选项4“树叶变色的机制”。')\"></span></span>これは植物の葉が<span class=\"keyword\" onclick=\"showTooltip(event, '枯（か）れる：枯萎。')\">枯れて</span>落ちる前に起こる現象で、老化現象の一種なんです。",
