            "html": "<span class=\"highlight-correct\"><span class=\"opt-tag tag-correct\">①</span><span class=\"explain-correct\" onclick=\"showTooltip(event, '男播音员在开头提出【去海外留学的日本学生正在减少（海外に留学する日本人学生が減少しています）】的现象后，后续全文都在列举学费涨价、可能对求职不利、企业不重视海外经验等具体的影响因素。这说明整段报道都在探讨留学生减少的真正原因，符合选项1。')\">この十年、海外に留学する日本人学生が減少しています。</span></span>",
