  "2016.12-6": {
    "sampleAccurate": true,
    "endGuard": 0.06,
    "fadeOut": 0.018,
    "alignment": {
      "status": "user-approved",
      "humanAuditionPassed": false,
      "publicationApproval": {
        "type": "explicit-user-approval",
        "record": "output/audio/timeline-review/summary-n1-2016-12-redo/publication-approval.json",
        "candidateSha256": "92b389dc9d31ae1fddc01e1f32ccdcf39dce6f25ac15161ff135241ea03a13ba"
      }
    },
    "question": {
      "src": "../assets/audio/2016.12-6.mp3",
      "start": 5.26,
      "end": 8.49,
      "status": "candidate",
      "humanAuditionPassed": false
    },
    "lines": [
      {
        "src": "../assets/audio/2016.12-6.mp3",
        "start": 10.25,
        "end": 23.22,
        "segments": [
          {
            "src": "../assets/audio/2016.12-6.mp3",
            "start": 10.25,
            "end": 14.7,
            "status": "candidate",
            "humanAuditionPassed": false,
            "html": "私は長年鮭の<span class=\"keyword\" onclick=\"showTooltip(event, '生態（せいたい）：生态。')\">生態</span>を調査研究してきました。",
            "trans": "（我长年从事鲑鱼生态的调查研究。）"
          },
          {
            "src": "../assets/audio/2016.12-6.mp3",
            "start": 15.36,
            "end": 23.22,
            "status": "candidate",
            "humanAuditionPassed": false,
            "html": "鮭は川で生まれ、遠く離れた海で育ち、また生まれた川に帰って<span class=\"keyword\" onclick=\"showTooltip(event, '産卵（さんらん）：产卵。')\">産卵</span>し、その一生を終えます。",
            "trans": "（鲑鱼在河里出生，在遥远的海洋中长大，然后再回到出生的河流中产卵，结束其一生。）"
          }
        ]
      },
      {
        "src": "../assets/audio/2016.12-6.mp3",
        "start": 23.97,
        "end": 36.32,
        "segments": [
          {
            "src": "../assets/audio/2016.12-6.mp3",
            "start": 23.97,
            "end": 27.38,
            "status": "candidate",
            "humanAuditionPassed": false,
            "html": "川にはその川ごとの<span class=\"keyword\" onclick=\"showTooltip(event, '特有（とくゆう）：特有，独有。')\">特有</span>の匂いがあります。",
            "trans": "（河流有着每条河特有的气味。）"
          },
          {
            "src": "../assets/audio/2016.12-6.mp3",
            "start": 28.07,
            "end": 36.32,
            "status": "candidate",
            "humanAuditionPassed": false,
            "html": "これまでの調査から鮭は川に帰る際、一つは川の匂いを<span class=\"keyword\" onclick=\"showTooltip(event, '頼（たよ）り：依靠，依赖。')\">頼り</span>としていることがあきらかになっています。",
            "trans": "（从迄今为止的调查中已经查明，鲑鱼在游回河流时，其中一个是依靠着河流的气味。）"
          }
        ]
      },
      {
        "src": "../assets/audio/2016.12-6.mp3",
        "start": 36.82,
        "end": 55.7,
        "segments": [
          {
            "src": "../assets/audio/2016.12-6.mp3",
            "start": 36.82,
            "end": 44.93,
            "status": "candidate",
            "humanAuditionPassed": false,
            "html": "しかし、鮭は何千キロも離れた海まで移動するため、川の匂いだけを頼りにしているとは考えにくいのです。",
            "trans": "（但是，由于鲑鱼会移动到几千公里外的海域，因此很难想象它们仅仅是依靠河流的气味。）"
          },
          {
            "src": "../assets/audio/2016.12-6.mp3",
            "start": 45.59,
            "end": 55.7,
            "status": "candidate",
            "humanAuditionPassed": false,
            "html": "まだ明らかにされていないこともありますが。<span class=\"highlight-correct\"><span class=\"opt-tag tag-correct\">②</span><span class=\"explain-correct\" onclick=\"showTooltip(event, '男人在最后总结了他的研究观点：除了依靠气味，【被认为同时使用了好几种方法，比如根据太阳的位置来掌握当前的位置等（太陽の位置をもとに、現在の位置を把握するなど、いくつかのことを併用していると考えられています）】。这说明整段讲话都在探讨鲑鱼是如何找到路回到出生地的，完全符合选项2“回到出生地的方法”。')\">太陽の位置をもとに、現在の位置を<span class=\"keyword\" onclick=\"showTooltip(event, '把握（はおく）：掌握，把握。')\">把握</span>するなど、いくつかのことを<span class=\"keyword\" onclick=\"showTooltip(event, '併用（へいよう）：并用，同时使用。')\">併用</span>していると考えられています。</span></span><span class=\"highlight-correct\"><span class=\"explain-correct\" onclick=\"showTooltip(event, '男人在最后总结了他的研究观点：除了依靠气味，【被认为同时使用了好几种方法，比如根据太阳的位置来掌握当前的位置等（太陽の位置をもとに、現在の位置を把握するなど、いくつかのことを併用していると考えられています）】。这说明整段讲话都在探讨鲑鱼是如何找到路回到出生地的，完全符合选项2“回到出生地的方法”。')\"></span></span><span class=\"highlight-wrong\"><span class=\"opt-tag tag-wrong\">①③④</span><span class=\"explain-wrong\" onclick=\"showTooltip(event, '关于选项1，文中探讨的是鲑鱼如何从海里回到出生的河里，而不是“为什么”从河里去海里，排除。关于选项3，文中提到气味只是作为鲑鱼认路的一种手段，并没有专门探讨它喜欢的“气味的特征”，排除。关于选项4，虽然提到了河流环境，但文中根本没有提及需要“保护环境”，排除。')\"></span></span>",
            "trans": "（虽然还有尚未查明的事情。被认为同时使用了好几种方法，比如根据太阳的位置来掌握当前的位置等。）"
          }
        ]
      },
      {
        "src": "../assets/audio/2016.12-6.mp3",
        "start": 61.46,
        "end": 65.62,
        "status": "candidate",
        "humanAuditionPassed": false
      }
    ]
  },
