            "html": "日本には、農村地域などに<span class=\"keyword\" onclick=\"showTooltip(event, '屋敷林（やしきりん）：宅旁林，防风林。')\">屋敷林</span>といって、家の周りに植えられた<span class=\"keyword\" onclick=\"showTooltip(event, '人工的（じんこうてき）：人工的。')\">人工的</span>な林があります。",
