            "end": 25.9,
            "status": "candidate",
            "humanAuditionPassed": false,
            "html": "強い季節風から家屋を守ったり、枝や<span class=\"keyword\" onclick=\"showTooltip(event, '幹（みき）：树干。')\">幹</span>を木材として、生活の中で使ったりという機能がありました。",
