            "humanAuditionPassed": false,
            "html": "私も70をすぎ、何匹も面倒を見ることはできませんから、いつも一匹ずつ<span class=\"keyword\" onclick=\"showTooltip(event, '向（む）き合（あ）う：面对，相对。')\">向き合って</span>います。",
