            "html": "<span class=\"highlight-correct\"><span class=\"opt-tag tag-correct\">④</span><span class=\"explain-correct\" onclick=\"showTooltip(event, '建筑家在肯定了准备的重要性后，紧接着用“但是（ただし）”进行了转折，指出【这仅限于不是创造性物品的情况】。随后全文都在讲述在将构想成型（即制造创造性物品）时，碰壁和失败是提供营养的必要过程，不要害怕失败。这完全符合选项4“制造创造性物品时重要的事情”。')\"><span class=\"keyword\" onclick=\"showTooltip(event, '発想（はっそう）：构想，想法。')\">発想</span>を形にするには何度も壁にぶつかって、失敗しては<span class=\"keyword\" onclick=\"showTooltip(event, 'やり直（なお）す：重做，重新来过。')\">やり直す</span>。</span></span>",
