            "end": 50.15,
            "status": "candidate",
            "humanAuditionPassed": false,
            "html": "まあ、<span class=\"highlight-wrong\"><span class=\"opt-tag tag-wrong\">②</span><span class=\"explain-wrong\" onclick=\"showTooltip(event, '关于选项2，作词家说【一开始是为了作词用的笔记本，但最近不仅如此……（最初は作詞のためのノートだったんですけど、最近はそれだけじゃなくて……）】，说明他不是单纯在讲作词的方法，而是分享一种记录灵感的方式，可以排除。')\">最初は作詞のためのノートだったんですけど、最近はそれだけじゃなくて、やってみたいこととか、今月の目標とか、思いついたことをなんでも<span class=\"keyword\" onclick=\"showTooltip(event, '書（か）き留（と）める：记下，写下。')\">書き留めて</span>おくノートとして使っています。</span></span>",
            "trans": "（嘛，虽然一开始是为了作词用的笔记本，但最近不仅如此，我还把它当作把想做的事、这个月的目标、想到的事情什么都记下来的笔记本在使用。）"
